list_order_flags.code:
final response = await client.orderFlags
    .listOrderFlags(queryParams: {'limit': 20});
final orderFlags = (response.map as Map)['order_flags'] as List;
for (final orderFlag in orderFlags) {
  print('${(orderFlag as Map)['id']} ${orderFlag['name']}');
}

create_order_flag.code:
final response = await client.orderFlags.createOrderFlag({
  'order_flag': {
    'name': 'Awaiting Stock',
    'color': '#5A7BD4',
    'description': 'Waiting for stock to arrive.',
  },
});
final orderFlag = (response.map as Map)['order_flag'] as Map;
print(orderFlag['id']);

get_order_flag.code:
final response = await client.orderFlags.getOrderFlag(2);
final orderFlag = (response.map as Map)['order_flag'] as Map;
print('${orderFlag['name']} ${orderFlag['color']}');

update_order_flag.code:
final response = await client.orderFlags.updateOrderFlag(4, {
  'order_flag': {
    'name': 'Awaiting Stock',
    'color': '#B02E2E',
    'description': 'Waiting for stock from the supplier.',
  },
});
final orderFlag = (response.map as Map)['order_flag'] as Map;
print('${orderFlag['color']} ${orderFlag['description']}');
